import{_ as l,a0 as o,w as d,s as h,I as e,x as a,a1 as i,A as t,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"通過 SSH 在遠程 Linux 系統上執行命令 | LCTT x X-CMD","titleTemplate":false,"description":"通過 SSH 在遠程 Linux 系統上執行命令 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通過 SSH 在遠程 Linux 系統上執行命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通過 SSH 在遠程 Linux 系統上執行命令 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20220929 Execute Commands On Remote Linux Systems Via SSH","title":"通過 SSH 在遠程 Linux 系統上執行命令","tag":"202211","desc":""},"relativePath":"202211/20220929 Execute Commands On Remote Linux Systems Via SSH.md","filePath":"[post].md"}'),r={name:"202211/20220929 Execute Commands On Remote Linux Systems Via SSH.md"};function c(u,s,g,k,b,m){const n=o("Link");return d(),h("div",null,[s[29]||(s[29]=e("h1",{id:"通過-ssh-在遠程-linux-系統上執行命令",tabindex:"-1"},[a("通過 SSH 在遠程 Linux 系統上執行命令 "),e("a",{class:"header-anchor",href:"#通過-ssh-在遠程-linux-系統上執行命令","aria-label":"Permalink to “通過 SSH 在遠程 Linux 系統上執行命令”"},"​")],-1)),s[30]||(s[30]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202211/17/163910g9u42ssfcuk9c290.jpg",alt:""})],-1)),s[31]||(s[31]=e("blockquote",null,[e("p",null,"通過安全的網絡連接在遠程計算機上調用命令或程序。")],-1)),e("p",null,[s[1]||(s[1]=a("有一天，我正在測試如何在 ",-1)),i(n,{href:"https://ostechnix.com/how-to-keep-ownership-and-file-permissions-intact-when-copying-files-or-directories/"},{default:t(()=>[...s[0]||(s[0]=[a("將文件或目錄複製到多個位置和系統時保持完整的文件權限",-1)])]),_:1}),s[2]||(s[2]=a("。當我想檢查遠程系統上的文件權限時，我必須通過 SSH 登錄它並檢查屬性。從遠程系統多次登錄和註銷的過程讓我有點煩，我想，如果我可以",-1)),s[3]||(s[3]=e("strong",null,"在遠程 Linux 系統上通過 SSH 執行命令",-1)),s[4]||(s[4]=a("就好了。",-1))]),s[32]||(s[32]=p('<p>幸運的是，在瀏覽了 <code>ssh</code> 命令的手冊頁後，我找到了一個解決辦法。</p><p>如果你想知道如何本地運行遠程系統上運行命令或腳本，而不登錄到遠程系統，下面的內容會告訴你如何做。</p><h3 id="_1、通過-ssh-在遠程-linux-系統上執行命令" tabindex="-1">1、通過 SSH 在遠程 Linux 系統上執行命令 <a class="header-anchor" href="#_1、通過-ssh-在遠程-linux-系統上執行命令" aria-label="Permalink to “1、通過 SSH 在遠程 Linux 系統上執行命令”">​</a></h3><p>從本地系統通過 SSH 在遠程系統上運行命令或腳本的典型方法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh &lt;username@IP_Address-or-Doman_name&gt; &lt;Command-or-Script&gt;</span></span></code></pre></div><p>允許我給你們舉幾個例子：</p><h4 id="_1-1、通過-ssh-在遠程系統上運行單個命令" tabindex="-1">1.1、通過 SSH 在遠程系統上運行單個命令 <a class="header-anchor" href="#_1-1、通過-ssh-在遠程系統上運行單個命令" aria-label="Permalink to “1.1、通過 SSH 在遠程系統上運行單個命令”">​</a></h4>',7)),e("p",null,[s[6]||(s[6]=a("假設你想要 ",-1)),i(n,{href:"https://ostechnix.com/find-out-the-linux-distribution-name-version-and-kernel-details/"},{default:t(()=>[...s[5]||(s[5]=[a("查找遠程 Linux 系統的內核詳細信息",-1)])]),_:1}),s[7]||(s[7]=a("。為此，只需運行：",-1))]),s[33]||(s[33]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh sk@192.168.225.22 uname -a</span></span></code></pre></div><p>這裏，</p><ul><li><code>sk</code> 是遠程系統的用户名，</li><li><code>192.168.225.22</code> 是遠程系統的 IP 地址，</li><li><code>uname -a</code> 是我想在遠程系統上運行的命令。</li></ul><p>示例輸出：</p><p><img src="https://ostechnix.com/wp-content/uploads/2019/12/Execute-Commands-On-Remote-Linux-Systems-Via-SSH.gif" alt="通過 SSH 在遠程 Linux 系統上執行命令"></p><p>看到沒？我並沒有實際登錄到遠程系統，但通過 SSH 在遠程系統上執行了 <code>uname</code> 命令，並在本地系統的終端上顯示了輸出。</p><p>你還可以像下面這樣用引號指定命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh sk@192.168.225.22 &quot;uname -a&quot;</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh sk@192.168.225.22 &#39;uname -a&#39;</span></span></code></pre></div>',10)),e("p",null,[s[9]||(s[9]=a("如果你已經 ",-1)),i(n,{href:"https://ostechnix.com/how-to-change-apache-ftp-and-ssh-default-port-to-a-custom-port-part-3/"},{default:t(()=>[...s[8]||(s[8]=[a("更改了 SSH 協議的默認端口",-1)])]),_:1}),s[10]||(s[10]=a("，只需使用 ",-1)),s[11]||(s[11]=e("code",null,"-p",-1)),s[12]||(s[12]=a(" 參數指定它。",-1))]),s[34]||(s[34]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -p 2200 sk@192.168.225.22 uname -a</span></span></code></pre></div><h4 id="_1-2、通過-ssh-在遠程主機上執行多個命令" tabindex="-1">1.2、通過 SSH 在遠程主機上執行多個命令 <a class="header-anchor" href="#_1-2、通過-ssh-在遠程主機上執行多個命令" aria-label="Permalink to “1.2、通過 SSH 在遠程主機上執行多個命令”">​</a></h4><p>你還可以在遠程主機上運行多個命令，方法是將它們放在引號中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh sk@192.168.225.22 &quot;uname -r &amp;&amp; lsb_release -a&quot;</span></span></code></pre></div><p>或者：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh sk@192.168.225.22 &quot;uname -r ; lsb_release -a&quot;</span></span></code></pre></div><p>上面的命令將顯示我的 Ubuntu 服務器的內核版本和發行版詳細信息。</p><p>示例輸出：</p><p><img src="https://ostechnix.com/wp-content/uploads/2019/12/Run-multiple-commands-on-remote-systems-via-SSH-on-Linux.png" alt="在 Linux 上通過 SSH 在遠程主機上運行多個命令"></p><p>正如一位讀者在下面的評論部分提到的那樣，你應該用引號指定多個命令。如果不使用引號，第一個命令將在遠程系統上執行，第二個命令將僅在本地計算機上執行。整個帶引號的命令將按預期在遠程計算機上運行。</p><blockquote><p><strong>提示：</strong> 瞭解 <code>&amp;&amp;</code> 和 <code>;</code> 在命令中的區別：</p><p><code>&amp;&amp;</code> 操作符只有在第一個命令成功時才執行第二個命令。</p><p>示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get update &amp;&amp; sudo apt-get upgrade</span></span></code></pre></div><p>在上述示例中，如果第一個命令成功，才會執行 <code>sudo apt-get upgrade</code>。否則，它將不會運行。</p><p><code>;</code> 操作符會執行第二個命令，無論第一個命令是成功還是失敗。</p><p>示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get update ; sudo apt-get upgrade</span></span></code></pre></div><p>在上述示例中，即使第一個命令失敗，<code>sudo apt-get upgrade</code> 也會執行。</p></blockquote><h4 id="_1-3、通過-ssh-在遠程機器上調用有-sudo-權限的命令" tabindex="-1">1.3、通過 SSH 在遠程機器上調用有 sudo 權限的命令 <a class="header-anchor" href="#_1-3、通過-ssh-在遠程機器上調用有-sudo-權限的命令" aria-label="Permalink to “1.3、通過 SSH 在遠程機器上調用有 sudo 權限的命令”">​</a></h4><p>有些命令需要 <code>sudo</code> 權限才能運行。例如，以下命令將在我的遠程系統上安裝 <code>apache2</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -t sk@192.168.225.22 sudo apt install apache2</span></span></code></pre></div><p>示例輸出：</p><p><img src="https://ostechnix.com/wp-content/uploads/2019/12/Run-commands-with-sudo-privileges-on-remote-systems-via-SSH.png" alt="通過 SSH 在遠程機器上運行有 Sudo 權限的命令"></p><p>注意到了嗎？我在上面的命令中使用了 <code>-t</code> 標誌，我們需要使用它來強制進行偽終端分配。它用於在遠程機器上執行任意基於屏幕的程序，這非常有用。例如，在實現菜單服務時。</p><p>另外，我輸入了<strong>兩次</strong>密碼。第一次是遠程用户的密碼，以便從本地系統通過 SSH 訪問遠程系統，第二次是為了向遠程用户賦予 sudo 權限，以便安裝應用程序（在本例中為 apache2）。</p><p>讓我們用以下命令檢查 Apache 服務是否正在運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -t sk@192.168.225.22 sudo systemctl status apache2</span></span>
<span class="line"><span>sk@192.168.225.22&#39;s password: </span></span>
<span class="line"><span>[sudo] password for sk: </span></span>
<span class="line"><span>● apache2.service - The Apache HTTP Server</span></span>
<span class="line"><span>Loaded: loaded (/lib/systemd/system/apache2.service; enabled; vendor preset: enabled)</span></span>
<span class="line"><span>Drop-In: /lib/systemd/system/apache2.service.d</span></span>
<span class="line"><span>└─apache2-systemd.conf</span></span>
<span class="line"><span>Active: active (running) since Thu 2019-12-19 11:08:03 UTC; 52s ago</span></span>
<span class="line"><span>Main PID: 5251 (apache2)</span></span>
<span class="line"><span>Tasks: 55 (limit: 2318)</span></span>
<span class="line"><span>CGroup: /system.slice/apache2.service</span></span>
<span class="line"><span>├─5251 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span>├─5253 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span>└─5254 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Dec 19 11:08:03 ubuntuserver systemd[1]: Starting The Apache HTTP Server...</span></span>
<span class="line"><span>Dec 19 11:08:03 ubuntuserver apachectl[5227]: AH00558: apache2: Could not reliably determine the server&#39;s fully qualified domain name, using 2409:4072:51f:a1b6:a00:27ff:f</span></span>
<span class="line"><span>Dec 19 11:08:03 ubuntuserver systemd[1]: Started The Apache HTTP Server.</span></span></code></pre></div><p>同樣的，我們可以通過 SSH 在本地系統上運行遠程系統上的任何命令或腳本。</p><h4 id="_1-4、通過-ssh-在遠程系統上運行本地腳本" tabindex="-1">1.4、通過 SSH 在遠程系統上運行本地腳本 <a class="header-anchor" href="#_1-4、通過-ssh-在遠程系統上運行本地腳本" aria-label="Permalink to “1.4、通過 SSH 在遠程系統上運行本地腳本”">​</a></h4><p>讓我們在本地系統上創建一個簡單的腳本來顯示關於遠程系統的發行版名稱、包管理和基本細節等。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi system_information.sh</span></span></code></pre></div><p>添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>#Name: Display System Details</span></span>
<span class="line"><span>#Owner: OSTechNIx</span></span>
<span class="line"><span>#----------------------------</span></span>
<span class="line"><span>echo /etc/*_ver* /etc/*-rel*; cat /etc/*_ver* /etc/*-rel*</span></span></code></pre></div><p>按下 <code>ESC</code> 鍵，輸入 <code>:wq</code> 保存退出。</p><p>現在，通過 SSH 命令在遠程系統上運行這個腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh sk@192.168.225.22 &#39;bash -s&#39; &lt; system_information.sh</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sk@192.168.225.22&#39;s password: </span></span>
<span class="line"><span>/etc/debian_version /etc/lsb-release /etc/os-release</span></span>
<span class="line"><span>buster/sid</span></span>
<span class="line"><span>DISTRIB_ID=Ubuntu</span></span>
<span class="line"><span>DISTRIB_RELEASE=18.04</span></span>
<span class="line"><span>DISTRIB_CODENAME=bionic</span></span>
<span class="line"><span>DISTRIB_DESCRIPTION=&quot;Ubuntu 18.04.2 LTS&quot;</span></span>
<span class="line"><span>NAME=&quot;Ubuntu&quot;</span></span>
<span class="line"><span>VERSION=&quot;18.04.2 LTS (Bionic Beaver)&quot;</span></span>
<span class="line"><span>ID=ubuntu</span></span>
<span class="line"><span>ID_LIKE=debian</span></span>
<span class="line"><span>PRETTY_NAME=&quot;Ubuntu 18.04.2 LTS&quot;</span></span>
<span class="line"><span>VERSION_ID=&quot;18.04&quot;</span></span>
<span class="line"><span>HOME_URL=&quot;https://www.ubuntu.com/&quot;</span></span>
<span class="line"><span>SUPPORT_URL=&quot;https://help.ubuntu.com/&quot;</span></span>
<span class="line"><span>BUG_REPORT_URL=&quot;https://bugs.launchpad.net/ubuntu/&quot;</span></span>
<span class="line"><span>PRIVACY_POLICY_URL=&quot;https://www.ubuntu.com/legal/terms-and-policies/privacy-policy&quot;</span></span>
<span class="line"><span>VERSION_CODENAME=bionic</span></span>
<span class="line"><span>UBUNTU_CODENAME=bionic</span></span></code></pre></div><p>如果你沒有在上面的命令中指定 <code>bash -s</code>，你將獲得遠程系統的詳細信息，但偽終端不會被分配。</p><h4 id="_1-5、將遠程主機的命令輸出保存到本地主機" tabindex="-1">1.5、將遠程主機的命令輸出保存到本地主機 <a class="header-anchor" href="#_1-5、將遠程主機的命令輸出保存到本地主機" aria-label="Permalink to “1.5、將遠程主機的命令輸出保存到本地主機”">​</a></h4><p>如果你希望與支持團隊或同事共享遠程系統上運行的命令輸出，那麼這非常有用。</p><p>以下命令將通過 SSH 在遠程系統運行 <code>du -ah</code>，並將輸出保存在本地系統的 <code>diskusage.txt</code> 文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh sk@192.168.225.22 du -ah &gt; diskusage.txt</span></span></code></pre></div><p>然後，你可以通過使用 <code>cat</code> 命令或文本編輯器查看 <code>diskusage.txt</code> 文件來分析磁盤使用細節。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat diskusage.txt </span></span>
<span class="line"><span>4.0K ./.profile</span></span>
<span class="line"><span>4.0K ./.gnupg/private-keys-v1.d</span></span>
<span class="line"><span>8.0K ./.gnupg</span></span>
<span class="line"><span>76K ./data/image.jpg</span></span>
<span class="line"><span>128K ./data/file.pdf</span></span>
<span class="line"><span>20K ./data/text.docx</span></span>
<span class="line"><span>5.9M ./data/audio.mp3</span></span>
<span class="line"><span>6.1M ./data</span></span>
<span class="line"><span>0 ./.sudo_as_admin_successful</span></span>
<span class="line"><span>4.0K ./pacman?inline=false</span></span>
<span class="line"><span>4.0K ./.bash_logout</span></span>
<span class="line"><span>4.0K ./.wget-hsts</span></span>
<span class="line"><span>4.0K ./.bash_history</span></span>
<span class="line"><span>0 ./.cache/motd.legal-displayed</span></span>
<span class="line"><span>4.0K ./.cache</span></span>
<span class="line"><span>4.0K ./deb-pacman_1.0-0.deb</span></span>
<span class="line"><span>4.0K ./.bashrc</span></span>
<span class="line"><span>6.2M .</span></span></code></pre></div><h4 id="_1-6、配置-ssh-密鑰認證-避免輸入密碼" tabindex="-1">1.6、配置 SSH 密鑰認證，避免輸入密碼 <a class="header-anchor" href="#_1-6、配置-ssh-密鑰認證-避免輸入密碼" aria-label="Permalink to “1.6、配置 SSH 密鑰認證，避免輸入密碼”">​</a></h4><p>如果你經常在遠程系統上運行命令，你可能需要配置基於 SSH 密鑰的身份驗證，以便每次跳過密碼輸入。更多細節可以在以下鏈接中找到。</p>`,40)),e("blockquote",null,[e("p",null,[e("strong",null,[i(n,{href:"https://ostechnix.com/configure-ssh-key-based-authentication-linux/"},{default:t(()=>[...s[13]||(s[13]=[a("Linux 系統下如何配置 SSH 密鑰認證",-1)])]),_:1})])])]),s[35]||(s[35]=p('<p>配置了基於 SSH 密鑰的認證後，我們可以通過 SSH 在遠程機器上執行命令，從而不需要輸入密碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh sk@192.168.225.22 sudo apt update</span></span></code></pre></div><h3 id="_2、通過-sshpass-在遠程機器上運行命令" tabindex="-1">2、通過 sshpass 在遠程機器上運行命令 <a class="header-anchor" href="#_2、通過-sshpass-在遠程機器上運行命令" aria-label="Permalink to “2、通過 sshpass 在遠程機器上運行命令”">​</a></h3><p>如果你不想配置基於 SSH 密鑰的身份驗證，你可以使用 <code>sshpass</code> 實用程序。</p><h4 id="_2-1、什麼是-sshpass" tabindex="-1">2.1、什麼是 sshpass? <a class="header-anchor" href="#_2-1、什麼是-sshpass" aria-label="Permalink to “2.1、什麼是 sshpass?”">​</a></h4><p><code>sshpass</code> 是為使用鍵盤交互密碼身份驗證模式運行 ssh 而設計的，但它以非交互的方式。簡單來説，<code>sshpass</code> 提供了非交互式的方式來驗證 SSH 會話。</p><p>SSH 使用直接 TTY 訪問來確保密碼確實是由交互式鍵盤用户發出的。<code>sshpass</code> 在一個專用 tty 中運行 SSH，讓它誤以為從交互用户那裏獲得了密碼。</p><h4 id="_2-2、在-linux-中安裝-sshpass" tabindex="-1">2.2、在 Linux 中安裝 sshpass <a class="header-anchor" href="#_2-2、在-linux-中安裝-sshpass" aria-label="Permalink to “2.2、在 Linux 中安裝 sshpass”">​</a></h4><p>在許多 Linux 發行版的默認倉庫中都有 <code>sshpass</code> 實用程序。例如，在 Debian、Ubuntu 及其衍生版本中，你可以使用下面的命令來安裝 <code>sshpass</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install sshpass</span></span></code></pre></div><h4 id="_2-3、通過-ssh-和-sshpass-在遠程機器上執行命令" tabindex="-1">2.3、通過 SSH 和 sshpass 在遠程機器上執行命令 <a class="header-anchor" href="#_2-3、通過-ssh-和-sshpass-在遠程機器上執行命令" aria-label="Permalink to “2.3、通過 SSH 和 sshpass 在遠程機器上執行命令”">​</a></h4><p><code>sshpass</code> 可以通過參數接受密碼，或者通過環境變量讀取密碼，也可以從文本文件中讀取密碼。</p><p><strong>警告：</strong> 所有這些方法都是 <strong>高度不安全的</strong>。所有系統用户都可以通過 <code>ps</code> 命令看到命令中的密碼。<strong>不建議</strong>在生產中使用這些方法。最好使用基於密鑰的身份驗證。</p><p>讓我們看看每種方法的示例。</p><h5 id="將密碼作為參數提供" tabindex="-1">將密碼作為參數提供 <a class="header-anchor" href="#將密碼作為參數提供" aria-label="Permalink to “將密碼作為參數提供”">​</a></h5><p>將密碼作為參數提供，使用 <code>-p</code> 選項，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sshpass -p &lt;remote-password&gt; ssh remoteuser@ip-address &lt;command-to-execute&gt;</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sshpass -p ubuntu ssh ostechnix@192.168.1.30 uname -a</span></span></code></pre></div><p>其中，</p><ul><li><code>-p ubuntu</code> - 提供遠程系統的密碼。</li><li><code>ostechnix@192.168.1.30</code> - 遠程系統用户名和地址。</li><li><code>uname -a</code> - 要在遠程計算機上執行的命令。</li></ul><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Linux Ubuntu22CT 5.15.60-1-pve #1 SMP PVE 5.15.60-1 (Mon, 19 Sep 2022 17:53:17 +0200) x86_64 x86_64 x86_64 GNU/Linux</span></span></code></pre></div><h5 id="密碼作為環境變量提供" tabindex="-1">密碼作為環境變量提供 <a class="header-anchor" href="#密碼作為環境變量提供" aria-label="Permalink to “密碼作為環境變量提供”">​</a></h5><p>在這個方法中，我們聲明一個名為 <code>SSHPASS</code> 的環境變量，用遠程環境的密碼作為其值。然後我們使用 <code>-e</code> 標誌，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ SSHPASS=ubuntu sshpass -e ssh ostechnix@192.168.1.30 uname -a</span></span></code></pre></div><h5 id="從文本文件中讀取密碼" tabindex="-1">從文本文件中讀取密碼 <a class="header-anchor" href="#從文本文件中讀取密碼" aria-label="Permalink to “從文本文件中讀取密碼”">​</a></h5><p>使用 <code>echo</code> 命令在文本文件中追加密碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;ubuntu&quot; &gt; mypassword.txt</span></span></code></pre></div><p>現在，將密碼文件傳遞給帶有 <code>-f</code> 標誌的 <code>sshpass</code>，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sshpass -f mypassword.txt ssh ostechnix@192.168.1.30 uname -a</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/09/Execute-Commands-On-Remote-Machines-Over-SSH-With-sshpass.png" alt="通過 SSH 和 sshpass 在遠程機器上執行命令"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在本教程中，我們學習了一些通過安全的網絡連接在遠程計算機上調用命令或程序的方法。在所有的方法中，<code>sshpass</code> 方法是最不安全的，建議用户避免在生產系統中使用它。</p><hr>',35)),e("p",null,[s[15]||(s[15]=a("via: ",-1)),i(n,{href:"https://ostechnix.com/execute-commands-on-remote-linux-systems-via-ssh/"},{default:t(()=>[...s[14]||(s[14]=[a("https://ostechnix.com/execute-commands-on-remote-linux-systems-via-ssh/",-1)])]),_:1})]),e("p",null,[s[20]||(s[20]=a("作者：",-1)),i(n,{href:"https://ostechnix.com/author/sk/"},{default:t(()=>[...s[16]||(s[16]=[a("sk",-1)])]),_:1}),s[21]||(s[21]=a(" 選題：",-1)),i(n,{href:"https://github.com/lkxed"},{default:t(()=>[...s[17]||(s[17]=[a("lkxed",-1)])]),_:1}),s[22]||(s[22]=a(" 譯者：",-1)),i(n,{href:"https://github.com/MjSeven"},{default:t(()=>[...s[18]||(s[18]=[a("MjSeven",-1)])]),_:1}),s[23]||(s[23]=a(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[19]||(s[19]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[26]||(s[26]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[24]||(s[24]=[a("LCTT",-1)])]),_:1}),s[27]||(s[27]=a(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:t(()=>[...s[25]||(s[25]=[a("Linux中國",-1)])]),_:1}),s[28]||(s[28]=a(" 榮譽推出",-1))])])}const y=l(r,[["render",c]]);export{x as __pageData,y as default};
